const ELEMENT_PROP_KEYS = new Set(["theme","value","label","eyebrow","snapAt","build","accent","fontFamily","ink","background","scale","delay","grain","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "dark",
  value: "200+",
  label: "components, ready to drop in",
  eyebrow: "remocn registry",
  snapAt: 28,
  build: 12,
  accent: "#3B5BFD",
  fontFamily: "Onest",
  scale: 1,
  delay: 0,
  grain: true,
  speed: 1,
};

type ResClimbElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof ResClimbBase>;

const ResClimbInner = forwardRef<
  HTMLDivElement,
  ResClimbElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<ResClimb>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <ResClimbBase
          {...(componentProps as unknown as ComponentProps<typeof ResClimbBase>)}
        />
      </div>
    </Sequence>
  );
});

export const ResClimb = Interactive.withSchema({
  Component: ResClimbInner,
  componentName: "<ResClimb>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});
